        definition: 'A function z = f(x, y) assigns one height to every point of a region of the xy-plane, so its graph is a surface. The partial derivative f_x is obtained by holding y fixed and letting only x change: f_x = lim (f(x + dx, y) - f(x, y))/dx as dx -> 0, and f_y is defined the same way with x frozen. Freezing one variable slices the surface by a plane parallel to a coordinate plane, and the partial derivative is simply the slope of the tangent to that slice curve. The cost of this simplicity is that each partial sees change in one direction only, so two numbers f_x and f_y are needed to describe how the surface tilts at a point.',
        takeaway: 'A partial derivative is an ordinary derivative taken along a slice, so every one-variable rule still works once you decide which variables are frozen.',
