        definition: 'If u = f(x, y) and both x and y are functions of a single variable t, then u is really a function of t alone, and its ordinary derivative du/dt is called the total derivative. It is found without substitution by the chain rule du/dt = u_x dx/dt + u_y dy/dt: each term is the rate along one dependency path, from u through x (or y) to t. Grewal proves it by splitting the increment du into a part where only x changes and a part where only y changes, then letting dt -> 0, which needs u_x to be continuous. The payoff is that we can find rates for messy compositions without ever expanding them, and the same rule extends to u = f(x, y, z) with one extra term per variable.',
        takeaway: 'The total derivative adds one term for every path from the output to the independent variable, which is why a two-variable chain rule has two terms.',
        visual: 'dependency-path-tree',
