        definition: 'Two functions u(x, y) and v(x, y) are functionally related if one can be written as a function of the other, F(u, v) = 0, and Grewal states that the necessary and sufficient condition is that d(u, v)/d(x, y) = 0 identically. The reason is geometric: if u and v are tied by a relation, the map (x, y) -> (u, v) squashes the whole plane onto a curve, so every small area is sent to zero area. The test costs one Jacobian, but it must vanish for all x, y, not just at one point; a Jacobian that is zero only at isolated points only marks where the map folds. Once dependence is shown, the relation itself is found by algebra, often by recognising an addition formula.',
