        definition: 'A reduction formula connects an integral I_n with another integral of the same type but lower order, typically I_(n-2), plus a term that needs no further integration. It works because integration by parts moves one factor of the power into a derivative, and for sin and cos that derivative feeds a sin^2 = 1 - cos^2 (or cos^2 = 1 - sin^2) identity that splits the leftover integral into I_(n-2) and a copy of I_n which can be transposed. Applying the formula again and again walks the index down in steps of two until it reaches a base case, I_0 or I_1, which is elementary. The cost is bookkeeping rather than cleverness: about n/2 applications, each contributing one boundary term and one coefficient.',
        takeaway: 'Every reduction formula is a recurrence: find the step, find the base case, and the integral of any order is just the step repeated.',
