        definition: 'For the mixed integral I_(m,n) = integral of sin^m x cos^n x dx, Grewal writes the integrand as sin^(m-1) x times (cos^n x sin x) and integrates by parts, since cos^n x sin x has the antiderivative -cos^(n+1) x/(n+1). The new integral contains sin^(m-2) x cos^(n+2) x; writing cos^2 x = 1 - sin^2 x splits it into I_(m-2,n) and a copy of I_(m,n). Transposing that copy and dividing by (m+n)/(n+1) gives I_(m,n) = -(sin^(m-1) x cos^(n+1) x)/(m+n) + ((m-1)/(m+n)) I_(m-2,n). The formula lowers m by two while n stays fixed, so the denominator m+n shrinks by two at each step; a companion formula lowers n instead.',
        takeaway: 'In the mixed formula the denominator is the total power m + n, and only the power you are reducing appears in the numerator.',
        visual: 'mixed-power-grid-walk',
