        definition: 'On 0 to pi/2 the boundary term of the mixed formula vanishes, so I_(m,n) = ((m-1)/(m+n)) I_(m-2,n). Chaining m down, and then n down with the companion formula, produces one fraction: the numerator is (m-1)(m-3)... times (n-1)(n-3)..., each product stopping at 1 or 2, and the denominator is (m+n)(m+n-2)... down to 1 or 2. The extra factor pi/2 appears only when m and n are both even, because only then does the chain end at the integral of dx from 0 to pi/2; if either index is odd the chain ends at an elementary integral such as the integral of sin x cos^n x, giving a rational value. This single formula replaces pages of algebra for every definite mixed-power integral on this interval.',
