        definition: 'Row operations are only useful if they aim somewhere, and the target is the row echelon form U: the first non-zero entry of each row (the pivot) lies strictly to the right of the pivot in the row above, every entry below a pivot is zero, and all-zero rows sit at the bottom. The staircase is reached column by column: use the current pivot to create zeros beneath it, then step down one row and right to the next column that still has a non-zero entry. Because no step changes the rank, the number of pivots (equivalently, non-zero rows) in U is the rank of the original matrix. A column may have no pivot at all, and that skipped step in the staircase is exactly where free variables will come from later.',
        takeaway: 'The echelon form is where a matrix stops hiding its structure: pivots count the rank, and the columns without pivots are the degrees of freedom.',
        visual: 'echelon-staircase-3x4',
        visualSpec: 'Left: the 3x4 matrix A = [1 3 3 2 ; 2 6 9 7 ; -1 -3 3 4] in a grid. Right: its echelon form U = [1 3 3 2 ; 0 0 3 3 ; 0 0 0 0] in an identical grid. On U a thick staircase line runs under row 1, drops at column 3 (skipping column 2), runs under row 2, and drops to the bottom. Pivots 1 (row 1, col 1) and 3 (row 2, col 3) are circled in orange. Columns 2 and 4 are shaded grey and labelled \'no pivot: free\'. The zero row is tinted and labelled \'zero rows last\'. Caption under U: \'rank = number of pivots = 2\'. On reveal: A appears, arrows \'R2 - 2R1, R3 + R1\' pulse, U\'s first column of zeros appears, then \'R3 - 2R2\' clears row 3, then the staircase draws, the pivots circle, and finally the grey columns and caption fade in.',
