        definition: 'Choose any r rows and any r columns of A; the determinant of the r x r block they cross is a minor of order r. The rank rho(A) is r when at least one minor of order r is non-zero and every minor of order r + 1 vanishes, so rank measures the size of the largest square block that is still invertible. Two one-line consequences do most of the work: a single non-zero r x r minor proves rho(A) >= r, and all (r+1) x (r+1) minors being zero proves rho(A) <= r. The definition is exact but expensive, because an m x n matrix has C(m,r) x C(n,r) minors of order r, which is why in practice we use it only on small matrices or to confirm a result obtained by row reduction.',
        takeaway: 'Rank is the size of the biggest invertible square hiding inside the matrix, and one non-zero minor is enough to prove a lower bound.',
