        definition: 'When an entry of A is an unknown k, rank is no longer a single number but a function of k that stays at its maximum for almost every k and drops only at a few critical values. The reliable way to find those values is to carry k through the elimination untouched and look at the last pivot, which becomes an expression such as k - 7; the rank falls exactly when that expression is zero, and for a square matrix the same expression appears as det A. Grewal packages the final answer as the normal form: using row and column operations every matrix of rank r becomes [I_r 0 ; 0 0], so there exist non-singular P and Q with PAQ = N, and reading r from N is the same as counting pivots. The danger in parameter problems is dividing by an expression containing k, which silently assumes it is non-zero and hides exactly the case being asked about.',
