        definition: 'Gauss elimination solves AX = B by turning it into an equivalent upper triangular system UX = C and then reading the unknowns from the bottom up. In the forward stage each pivot is divided into the entries below it to get multipliers l = a_ij / pivot, and l times the pivot row is subtracted so that column becomes zero below the pivot; the right-hand side is carried along as an extra column so both sides receive the same operations. Back-substitution then solves the last equation for the last unknown and feeds each new value upward. Forward elimination costs about n^3/3 multiply-subtract steps and back-substitution only about n^2/2, which is why elimination is still the default direct method for dense systems and why most of the effort, and most of the hand-calculation errors, sit in the forward stage.',
        takeaway: 'Elimination does all the hard work turning the system into a triangle; back-substitution is cheap, so a wrong answer almost always means a slip in the forward stage.',
