        definition: 'Elimination divides by each pivot, so a zero in a pivot position stops it, and that zero can appear mid-way even when the original coefficient was non-zero. If some row below has a non-zero entry in that column, exchanging the two rows cures the problem and the system is still non-singular; if every entry below is zero the breakdown is permanent and the system is singular, with no solution or infinitely many. A tiny pivot is almost as bad: its multiplier becomes huge, and on a finite-precision calculator the huge multiple swamps the other row\'s information. Partial pivoting prevents both troubles by always bringing the numerically largest available coefficient of the current column into the pivot position before eliminating, which keeps every multiplier at most 1 in size; Grewal notes that complete pivoting (also exchanging columns) costs more and rarely improves accuracy.',
        takeaway: 'A pivot is a divisor, so choose the biggest one available: swapping rows costs nothing and keeps every multiplier at most 1 in size.',
        visual: 'pivot-swap-rescue',
        visualSpec: 'Left column: the augmented matrix after stage 1, [1 1 1 | 6 ; 0 0 1 | 3 ; 0 2 1 | 7], with the (2,2) zero circled red and a warning triangle \'pivot = 0\'. A curved double arrow swaps rows 2 and 3. Middle column: [1 1 1 | 6 ; 0 2 1 | 7 ; 0 0 1 | 3] with pivots 1, 2, 1 circled green, and the result \'z = 3, y = 2, x = 1\'. Right column, titled \'tiny pivot, 3 significant digits\': two stacked mini-panels. Upper panel \'no pivoting\': [0.0001 1 | 1 ; 1 1 | 2], multiplier 10000 in red, result \'x = 0.00, y = 1.00\' with a red cross. Lower panel \'partial pivoting\': rows swapped, multiplier 0.0001 in green, result \'x = 1.00, y = 1.00\' with a green tick. Footer: \'exact: x = 1.0001, y = 0.9999\'. On reveal: left matrix appears, the red circle pulses, the swap arrow animates, the middle matrix forms and the solution appears; then the right column\'s upper panel plays and gets its cross, the lower panel plays and gets its tick, and the footer appears last.',
