        definition: 'Direct methods such as Gauss elimination give the exact answer after a fixed n^3/3 operations; an iterative method instead starts from a guess (usually all zeros) and repeatedly improves it, each sweep costing only about n^2 operations, or far fewer when most coefficients are zero. The iteration comes from solving equation i for the unknown x_i on its diagonal, so the system becomes x = (known terms) - (small multiples of the other unknowns); if the off-diagonal multiples are small, each sweep shrinks the error. Grewal\'s working condition is diagonal dominance: in every equation the diagonal coefficient exceeds, in absolute value, the sum of the absolute values of the others, which is sufficient (not necessary) for convergence. Strang states the exact criterion -- the error is multiplied each sweep by a matrix whose largest eigenvalue magnitude, the spectral radius, must be below 1 -- and the practical lesson is that the same equations can converge or explode depending only on the order in which they are written.',
        takeaway: 'An iteration is only as good as its diagonal: reorder the equations so each unknown is solved from the equation where it dominates, or the guesses can run away.',
