        definition: 'Gauss-Seidel is the Jacobi iteration with one change: as soon as a new x is computed it replaces the old x in every formula that follows within the same sweep, so the y-formula already uses the new x and the z-formula uses the new x and y. Because each update works with fresher information, the error typically falls faster; in Grewal\'s 3x3 example Gauss-Seidel settles in 3 sweeps where Jacobi needs 6. Strang\'s 2x2 analysis quantifies it: for A = [2 -1 ; -1 2] Jacobi halves the error each sweep while Gauss-Seidel divides it by 4, so one Gauss-Seidel sweep is worth two Jacobi sweeps at the same arithmetic cost, and it needs only one copy of the unknowns in memory. The price is that the updates must be done in order, one after another, and like Jacobi it is guaranteed to converge only under conditions such as diagonal dominance.',
